INSERT INTO cat.categorias (nombre, nivel)
SELECT v.nombre, 0 FROM (VALUES
 ('Herramientas Manuales'),('Herramientas Eléctricas'),('Plomería'),
 ('Electricidad'),('Construcción'),('Pinturas'),('Tornillería y Fijación'),
 ('Jardinería'),('Seguridad y Cerrajería'),('Abrasivos y Corte'),
 ('Limpieza'),('Servicios'),('Renta de Equipo')
) v(nombre)
WHERE NOT EXISTS (SELECT 1 FROM cat.categorias c WHERE c.nombre = v.nombre AND c.nivel = 0);

-- Subcategorías por familia (nivel 1)
