-- Ruta legible para reportes
UPDATE cat.categorias h
SET ruta = p.nombre || ' > ' || h.nombre
FROM cat.categorias p
WHERE h.categoria_padre_id = p.categoria_id AND h.nivel = 1 AND h.ruta IS NULL;

