-- ADMINISTRADOR → todos los permisos
INSERT INTO seg.rol_permisos (rol_id, permiso_id)
SELECT r.rol_id, p.permiso_id
FROM seg.roles r CROSS JOIN seg.permisos p
WHERE r.clave = 'ADMINISTRADOR'
ON CONFLICT DO NOTHING;

-- GERENTE
INSERT INTO seg.rol_permisos (rol_id, permiso_id)
SELECT r.rol_id, p.permiso_id
FROM seg.roles r JOIN seg.permisos p
      ON p.clave IN ('V.VENDER','V.CANCELAR','V.DESCUENTO','V.COBRANZA','V.RENTAS',
                     'C.COMPRAR','C.PAGAR','I.AJUSTAR_STOCK','I.TRASLADAR',
                     'F.CAJA_ABRIR','F.CAJA_CORTAR','F.GASTOS_CREAR','ADM.REPORTES')
WHERE r.clave = 'GERENTE'
ON CONFLICT DO NOTHING;

-- ENCARGADO DE CAJA
INSERT INTO seg.rol_permisos (rol_id, permiso_id)
SELECT r.rol_id, p.permiso_id
FROM seg.roles r JOIN seg.permisos p
      ON p.clave IN ('V.VENDER','V.COBRANZA','F.CAJA_ABRIR','F.CAJA_CORTAR','ADM.REPORTES')
WHERE r.clave = 'ENCARGADO_CAJA'
ON CONFLICT DO NOTHING;

-- VENDEDOR
INSERT INTO seg.rol_permisos (rol_id, permiso_id)
SELECT r.rol_id, p.permiso_id
FROM seg.roles r JOIN seg.permisos p ON p.clave IN ('V.VENDER')
WHERE r.clave = 'VENDEDOR'
ON CONFLICT DO NOTHING;

-- ALMACENISTA
INSERT INTO seg.rol_permisos (rol_id, permiso_id)
SELECT r.rol_id, p.permiso_id
FROM seg.roles r JOIN seg.permisos p ON p.clave IN ('I.AJUSTAR_STOCK','I.TRASLADAR')
WHERE r.clave = 'ALMACENISTA'
ON CONFLICT DO NOTHING;

-- AUDITOR
INSERT INTO seg.rol_permisos (rol_id, permiso_id)
SELECT r.rol_id, p.permiso_id
FROM seg.roles r JOIN seg.permisos p ON p.clave IN ('ADM.REPORTES')
WHERE r.clave = 'AUDITOR'
ON CONFLICT DO NOTHING;

