ON CONFLICT (clave_sat) DO NOTHING;

INSERT INTO fis.tasas_impuesto (impuesto_id, tasa, factor, ambito, zona_frontera)
SELECT i.impuesto_id, x.tasa, x.factor, x.ambito, x.frontera
FROM (VALUES
    ('002', 0.1600::numeric, 'TASA'::text,  'VENTA'::text,  false),
    ('002', 0.1600, 'TASA',  'COMPRA', false),
    ('002', 0.0800, 'TASA',  'VENTA',  true),    -- franja fronteriza norte
    ('002', 0.0000, 'EXENTO','VENTA',  false),
    ('001', 0.0000, 'CUOTA', 'NOMINA', false)    -- ISR nómina: tablas en aplicación
) x(clave, tasa, factor, ambito, frontera)
JOIN fis.impuestos i ON i.clave_sat = x.clave
WHERE NOT EXISTS (
    SELECT 1 FROM fis.tasas_impuesto t
    WHERE t.impuesto_id = i.impuesto_id AND t.tasa = x.tasa
      AND t.factor = x.factor AND t.ambito = x.ambito
      AND t.zona_frontera = x.frontera);

