-- Mapeo formas de pago internas → catálogo SAT + comisiones bancarias ejemplo
UPDATE cat.formas_pago SET forma_pago_sat='01', comision_pct=0   WHERE clave='EFECTIVO';
UPDATE cat.formas_pago SET forma_pago_sat='28', comision_pct=2.5 WHERE clave='TARJETA_DEBITO';
UPDATE cat.formas_pago SET forma_pago_sat='04', comision_pct=3.5 WHERE clave='TARJETA_CREDITO';
UPDATE cat.formas_pago SET forma_pago_sat='03', comision_pct=0.5 WHERE clave='TRANSFERENCIA';
UPDATE cat.formas_pago SET forma_pago_sat='02', comision_pct=0   WHERE clave='CHEQUE';

SELECT 'PASO 3 COMPLETO: parametria cargada.' AS resultado,
       (SELECT COUNT(*) FROM cat.unidades_medida) AS unidades,
       (SELECT COUNT(*) FROM cat.categorias)      AS categorias,
       (SELECT COUNT(*) FROM seg.permisos)        AS permisos,
       (SELECT COUNT(*) FROM fis.tasas_impuesto)  AS tasas_impuesto;


-- ------------------------------------------------------------------
-- Backend: tokens de refresco JWT (rotacion en logout)
-- ------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS seg.refresh_tokens (
    refresh_token_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    usuario_id       INTEGER NOT NULL REFERENCES seg.usuarios(usuario_id) ON DELETE CASCADE,
    token_hash       VARCHAR(100) NOT NULL UNIQUE,
    expires_at       TIMESTAMPTZ NOT NULL,
    revoked_at       TIMESTAMPTZ,
    creado_en        TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_refresh_usuario ON seg.refresh_tokens(usuario_id);